{"method": "categoryProducts", "old_code": "        return $category->products->map(fn ($p) => [
            'label' => $p->label,
            'reviews_count' => $p->reviews->count(),
        ]);", "new_code": "        return $category->products()->withCount('reviews')->get()->map(fn ($p) => [
            'label' => $p->label,
